#!/usr/bin/env python3
"""Publish a verified best-known generator to its integration branch."""

from __future__ import annotations

import os
from pathlib import Path
import subprocess


BRANCH = "automation/best-known"
REPORT_PATH = Path("leaderboard/best-known.md")
ALLOWED_FILES = {
    "TableGeneration/BestKnown.lean",
    str(REPORT_PATH),
    # Generated by scripts/promote.py alongside BestKnown.lean.
    "TableGeneration/RecursiveCost/ArchivedCatalog.lean",
}
ALLOWED_PREFIX = "TableGeneration/Policies/Accepted/"


def run(args: list[str], *, capture: bool = False, check: bool = True) -> str:
    completed = subprocess.run(
        args,
        check=False,
        text=True,
        stdout=subprocess.PIPE if capture else None,
        stderr=subprocess.STDOUT if capture else None,
    )
    if check and completed.returncode != 0:
        raise RuntimeError(completed.stdout or f"command failed: {' '.join(args)}")
    # Preserve the leading columns in machine-readable `git status --short`
    # output; callers that parse JSON tolerate trailing whitespace.
    return (completed.stdout or "").rstrip("\n")


def changed_paths() -> list[str]:
    output = run(
        ["git", "status", "--short", "--untracked-files=all"],
        capture=True,
    )
    paths = []
    for line in output.splitlines():
        path = line[3:].strip()
        if " -> " in path:
            path = path.split(" -> ", 1)[1]
        paths.append(path)
    return paths


def allowed(path: str) -> bool:
    return path in ALLOWED_FILES or path.startswith(ALLOWED_PREFIX)


def compare_url() -> str | None:
    repository = os.getenv("GITHUB_REPOSITORY", "").strip()
    if not repository:
        return None
    server = os.getenv("GITHUB_SERVER_URL", "https://github.com").rstrip("/")
    return f"{server}/{repository}/compare/main...{BRANCH}?expand=1"


PR_TITLE = "feat: promote best-known table policies"
PR_BODY = f"""Generated by `.github/workflows/table-generation-promotion.yml`.

The branch holds the regenerated best-known generator, planner catalogue and
accepted-policy modules, built from the `submission-results` archive and
verified by the job that produced it. `{Path(__file__).name}` refuses to push
if promotion touched a path outside its allowlist.

Opened automatically so promotion does not wait on someone noticing the branch
moved. Review the diff before merging.
"""


def open_pull_request() -> None:
    """Open the promotion PR, or leave the existing one alone.

    Runs on every push to main, so it has to be idempotent: an open PR from
    this branch is the normal case, not an error. Nothing here is allowed to
    fail the job -- the branch is already pushed by this point, and losing the
    convenience of an auto-opened PR is not worth failing a verified
    promotion.

    A PR opened with GITHUB_TOKEN does not trigger workflows, by design, so it
    arrives without checks. The content was verified by this job; make the
    promotion checks required on the branch ruleset if that guarantee should
    be enforced at merge instead of assumed.
    """
    if not os.getenv("GH_TOKEN"):
        print("GH_TOKEN is unset; leaving the pull request to be opened by hand.")
        return
    existing = run(
        ["gh", "pr", "list", "--head", BRANCH, "--state", "open", "--json", "url",
         "--jq", ".[].url"],
        capture=True,
        check=False,
    ).strip()
    if existing:
        print(f"Promotion pull request already open: {existing}")
        return
    created = run(
        ["gh", "pr", "create", "--base", "main", "--head", BRANCH,
         "--title", PR_TITLE, "--body", PR_BODY],
        capture=True,
        check=False,
    ).strip()
    print(f"Opened promotion pull request: {created}" if created
          else "Could not open the promotion pull request; open it by hand.")


def report_branch() -> None:
    url = compare_url()
    message = f"Verified best-known branch: {BRANCH}"
    if url:
        message += f"\nReview and merge: {url}"
    print(message)

    summary = os.getenv("GITHUB_STEP_SUMMARY", "").strip()
    if summary:
        with Path(summary).open("a", encoding="utf-8") as output:
            output.write(REPORT_PATH.read_text(encoding="utf-8"))
            output.write("\n")
            output.write(f"Verified branch: `{BRANCH}`\n\n")
            if url:
                output.write(f"[Review changes against main]({url})\n")


def main() -> int:
    paths = changed_paths()
    disallowed = sorted(path for path in paths if not allowed(path))
    if disallowed:
        raise RuntimeError("promotion modified unexpected paths: " + ", ".join(disallowed))

    run(["git", "config", "user.name", "github-actions[bot]"])
    run(
        [
            "git",
            "config",
            "user.email",
            "41898282+github-actions[bot]@users.noreply.github.com",
        ]
    )
    run(["git", "checkout", "-B", BRANCH])
    if paths:
        run(["git", "add", "--", *paths])
        run(["git", "commit", "-m", "feat: promote best-known table policies"])
    else:
        print("Best-known generator is already current with main.")
    run(
        [
            "git",
            "fetch",
            "origin",
            f"refs/heads/{BRANCH}:refs/remotes/origin/{BRANCH}",
        ],
        check=False,
    )
    run(["git", "push", "--force-with-lease", "origin", f"HEAD:{BRANCH}"])
    open_pull_request()
    report_branch()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
